    ("Frameworks the proposed cases are written for.", {"es": "Los frameworks para los que se escriben los casos propuestos.", "pt": "Os frameworks para os quais os casos propostos são escritos.", "de": "Die Frameworks, für die die vorgeschlagenen Fälle geschrieben werden.", "fr": "Les frameworks pour lesquels les cas proposés sont écrits.", "it": "I framework per cui sono scritti i casi proposti."}),
    ("Proposed cases for", {"es": "Casos propuestos para", "pt": "Casos propostos para", "de": "Vorgeschlagene Fälle für", "fr": "Cas proposés pour", "it": "Casi proposti per"}),
    ("Pages to review", {"es": "Páginas a revisar", "pt": "Páginas a revisar", "de": "Zu prüfende Seiten", "fr": "Pages à analyser", "it": "Pagine da rivedere"}),
    ("How many pages to open, how deep, in which language, and whether to stay on this path.", {"es": "Cuántas páginas abrir, a qué profundidad, en qué idioma y si quedarse en esta ruta.", "pt": "Quantas páginas abrir, com que profundidade, em que idioma e se deve ficar neste caminho.", "de": "Wie viele Seiten geöffnet werden, wie tief, in welcher Sprache und ob die Prüfung auf diesem Pfad bleibt.", "fr": "Combien de pages ouvrir, à quelle profondeur, dans quelle langue, et s’il faut rester sur ce chemin.", "it": "Quante pagine aprire, a che profondità, in che lingua e se restare su questo percorso."}),
    ("Links deep", {"es": "Enlaces de profundidad", "pt": "Links de profundidade", "de": "Links tief", "fr": "Liens de profondeur", "it": "Link di profondità"}),
    ("Site default", {"es": "Predeterminado del sitio", "pt": "Padrão do site", "de": "Standard der Website", "fr": "Par défaut du site", "it": "Predefinita del sito"}),
    ("English", {"es": "Inglés", "pt": "Inglês", "de": "Englisch", "fr": "Anglais", "it": "Inglese"}),
    ("Spanish", {"es": "Español", "pt": "Espanhol", "de": "Spanisch", "fr": "Espagnol", "it": "Spagnolo"}),
    ("Portuguese", {"es": "Portugués", "pt": "Português", "de": "Portugiesisch", "fr": "Portugais", "it": "Portoghese"}),
    ("German", {"es": "Alemán", "pt": "Alemão", "de": "Deutsch", "fr": "Allemand", "it": "Tedesco"}),
